def solve(data):
    first = data['first']
    second = data['second']
    if data['first_end'] == 'front':
        first = first[::-1]
    if data['second_end'] == 'front':
        second = second[::-1]
    return first + second

def solve(data):
    active = {}
    parents = []
    names = []
    events = sorted(data['events'], key=lambda e: (e['minute'], e['seq']))
    for event in events:
        name = event['id']
        if event['kind'] == 'cancel':
            del active[name]
        else:
            parent = event['parent']
            parents.append(active.get(parent))
            names.append(name)
            active[name] = len(parents) - 1

    supported = set()
    for version, parent in enumerate(parents):
        if names[version] in active and (parent is None or parent in supported):
            supported.add(version)
    return sorted(name for name, version in active.items() if version not in supported)

import csv


def solve(data):
    text = data['text']
    lines = text.split('\n')
    physical_lines = [line.removesuffix('\r') for line in lines[:-1]]
    if lines[-1]:
        physical_lines.append(lines[-1])
    return list(csv.reader(physical_lines))
